                raw_declaration, f"{where} declaration",
                invalid=_cfada_invalid,
            )
            if parsed_declaration is None:
                raise _cfada_invalid(
                    f"{where} a counted row must carry its declaration"
                )
        parsed_rows.append({
            ADJ_CONCLUSION: conclusion,
            CP_DIGEST: digest,
            ID: row_id,
            VD_ISSUER: site,
            KEY_VERSION: row_key_version,
            ADJ_REASON: reason,
            _CFADA_DECLARATION: parsed_declaration,
        })

    common_declaration = _validated_pfda_declaration(
        payload[_CFADA_DECLARATION], "aggregate declaration",
        invalid=_cfada_invalid,
    )

    normalized_payload = {
        _CFADA_INPUTS: list(inputs),
        VD_ISSUER: issuer,
        ITEMS: parsed_rows,
        KEY_VERSION: key_version,
        _CFADA_PRUNE_POLICY_DIGEST: payload[_CFADA_PRUNE_POLICY_DIGEST],
        _CFADA_AUTHORIZATION_POLICY_DIGEST: payload[
            _CFADA_AUTHORIZATION_POLICY_DIGEST
        ],
        _CFADA_DECISION_SITE_POLICY_DIGEST: payload[
            _CFADA_DECISION_SITE_POLICY_DIGEST
        ],
        _CFADA_DECLARATION: common_declaration,
        STATUS: status,
        VERSION: CHAIN_FORK_AGGREGATE_DECISION_AGGREGATE_VERSION,
    }
    if _prune_compact({TICKET_PAYLOAD: normalized_payload,
                       SIGNATURE: signature}) != raw:
        raise _cfada_invalid(
            "aggregate packet encoding is not the canonical compact form"
        )
    return normalized_payload, signature


